const GUIDES = [{"slug": "best-hybrid-athlete-race-day-gear-and-recovery-tools-2026", "category": "Race Prep Checklist", "title": "The Complete 8-Station Functional Race Day & Recovery Checklist", "read_time": "6 min read", "summary": "From breathable 4.2 oz race tees and ventilated shoe duffles to deep-tissue percussion massagers and pneumatic compression boots\u2014how to pack and recover for race weekend.", "recommended_skus": ["APC-C01", "APC-C14", "APC-E01", "APC-E12"], "body_html": "\n        <p>Preparing for an 8-station functional endurance race requires training both your aerobic threshold and your compromised muscular stamina. Just as critical is the gear you wear across eight 1,000-meter runs and the recovery hardware you use in the 72 hours after crossing the finish line.</p>\n        <h4>1. Breathable Race Tees vs. Heavyweight Warmup Layers</h4>\n        <p>During a 60-to-90-minute indoor functional race, heat dissipation determines how well you hold your Zone 4 pace after heavy sled pushes and wall balls. Our <strong>Run. Station. Repeat. Functional Race Tee</strong> uses 4.2 oz Airlume combed ring-spun cotton that breathes through high-output stations without clinging, while our <strong>8.0 oz Fleece Warmup Hoodie</strong> keeps your core warm in the athlete corral before wave start.</p>\n        <h4>2. Compartment Organization in the Athlete Corral</h4>\n        <p>Nothing spikes pre-race stress faster than digging through a disorganized bag for electrolytes, chalk, or a spare pair of racing shoes. The <strong>8-Station Race Day 50L All-Weather Gym Duffle</strong> separates damp warmup gear from race essentials with a dedicated ventilated shoe tunnel.</p>\n        <h4>3. Post-Race Myofascial & Lymphatic Flushing</h4>\n        <p>Within two hours of finishing 100 wall balls and heavy sled pulls, eccentric micro-trauma peaks in the quads, calves, and lower back. Pairing a 12mm-amplitude <strong>ApexPulse Pro 3200 RPM Percussion Massager</strong> with 20 minutes in <strong>AirRecover Pneumatic Compression Boots</strong> accelerates venous return and cuts delayed-onset muscle soreness in half.</p>\n        "}, {"slug": "cold-plunge-and-red-light-recovery-routine-for-endurance-runners", "category": "Recovery Protocol", "title": "The Contrast & Red-Light Recovery Protocol for Hybrid Runners", "read_time": "5 min read", "summary": "How to sequence 11-minute weekly cold water immersion with 660nm/850nm near-infrared light wraps and far-infrared sauna blankets without blunting strength gains.", "recommended_skus": ["APC-E02", "APC-E03", "APC-E04", "APC-E15"], "body_html": "\n        <p>Endurance and hybrid athletes walk a tightrope between high weekly running mileage and heavy lower-body strength volume. Done at the right time, contrast therapy and red-light therapy let you stack back-to-back threshold days without joint breakdown.</p>\n        <h4>1. Timing Cold Immersion Around Strength Sessions</h4>\n        <p>To avoid blunting muscle protein synthesis immediately after heavy squats or sled work, schedule cold immersion at least 4 hours post-lift or on dedicated aerobic running days. The <strong>CryoPod 105-Gallon Insulated Portable Ice Bath Tub</strong> paired with the <strong>SubZero Floating Thermometer</strong> lets you lock in 50\u00b0F\u201355\u00b0F for 3-minute bouts right on your patio or balcony.</p>\n        <h4>2. 660nm + 850nm Light Therapy for Patellar & Achilles Tendons</h4>\n        <p>While surface cold calms acute inflammation, 850nm near-infrared wavelengths penetrate deep into tendons and joint capsules to support cellular recovery. Wrapping the <strong>InfraFlex 660nm + 850nm Therapy Belt</strong> around knees, ankles, or lower back for 15 minutes each evening restores tissue resilience before morning track intervals.</p>\n        <h4>3. Heat Acclimation via Far-Infrared Sauna Blankets</h4>\n        <p>Thirty minutes inside the <strong>ThermoCore Low-EMF Far-Infrared Sauna Blanket</strong> after training expands plasma volume and triggers heat-shock proteins\u2014giving apartment athletes the cardiovascular benefits of a traditional sauna with zero remodeling.</p>\n        "}, {"slug": "heavyweight-gym-pump-covers-and-functional-racing-apparel-guide", "category": "Apparel & Sizing", "title": "Heavyweight Pump Covers vs. Race-Weight Tees: How to Layer for Training", "read_time": "4 min read", "summary": "Why 6.5 oz carded cotton oversized tees and 8.0 oz fleece hoodies are the warmup standard before stripping down to 4.2 oz race-weight cotton.", "recommended_skus": ["APC-C02", "APC-C03", "APC-C08", "APC-C12"], "body_html": "\n        <p>Walk into any serious functional strength room from Southern California to Austin and you will notice a pattern: athletes warm up in structured, heavyweight cotton pump covers before stripping down to breathable race-weight tees once heart rates cross 160 BPM.</p>\n        <h4>1. What Makes a True Pump Cover?</h4>\n        <p>A proper warmup tee needs enough fabric weight (6.0 to 6.5 oz/yd\u00b2) to drape cleanly over the shoulders without clinging during barbell warmups. Our <strong>Wall Balls & Bad Decisions Heavyweight Pump Cover</strong> is cut with a relaxed drop-shoulder silhouette that holds its structure wash after wash.</p>\n        <h4>2. Breathable 4.2 oz Cotton for High-Output Stations</h4>\n        <p>Once you transition to 1,000-meter runs, burpee broad jumps, and erg intervals, fabric weight matters. Our <strong>Sled Push Enthusiast*</strong> and <strong>Sled Push Dept.</strong> tees use 4.2 oz Airlume combed ring-spun cotton printed with breathable water-based inks in the USA.</p>\n        "}, {"slug": "bulletproof-knees-and-shins-for-compromised-running", "category": "Strength & Durability", "title": "Bulletproofing Knees, Shins & Grip for Compromised Running", "read_time": "5 min read", "summary": "How to eliminate anterior shin splints, hamstring pulls, and farmer-carry grip fatigue using three compact home durability tools.", "recommended_skus": ["APC-E06", "APC-E09", "APC-E13", "APC-C04"], "body_html": "\n        <p>'Compromised running'\u2014transitioning immediately from heavy sleds, lunges, or farmer carries into a 1,000-meter run\u2014exposes every weak link in your lower kinetic chain and forearm flexors.</p>\n        <h4>1. Anterior Tibialis Training for High-Volume Pavement & Turf</h4>\n        <p>Most runners hammer their calves while completely neglecting the front of the shin. Two sets of 20 reps on the <strong>TibBar Pro Tibialis Anterior Strengthener</strong> three times a week decelerates foot slap under fatigue and armors your shins against medial tibial stress.</p>\n        <h4>2. Eccentric Hamstring Length with Nordic Curls</h4>\n        <p>When your quads are fatigued from sled pushes, your hamstrings take over hip extension on the run. Anchoring the <strong>NordicLock Hamstring Curl Door Strap</strong> under any closed door lets you build eccentric hamstring strength in 5 minutes flat.</p>\n        <h4>3. Measuring Isometric Grip Readiness</h4>\n        <p>Your grip is a direct indicator of central nervous system recovery. Testing your morning crush strength on the <strong>GripForge 198-Lb Digital Dynamometer</strong> tells you immediately whether your nervous system is recovered from yesterday's heavy carries.</p>\n        "}, {"slug": "home-recovery-corner-setup-under-300-for-endurance-athletes", "category": "Home Recovery Setup", "title": "How to Build an Apartment Mobility & Recovery Corner Under $250", "read_time": "4 min read", "summary": "Turn a 6x6 foot living room corner into an evening wind-down and myofascial release zone with vibrating foam rollers, acupressure mats, and warm-sunset lighting.", "recommended_skus": ["APC-E05", "APC-E07", "APC-E10", "APC-E14"], "body_html": "\n        <p>You don't need a three-car garage to recover like a full-time endurance athlete. By dedicating a single 6x6-foot corner of your living room or bedroom to evening mobility, you can noticeably improve overnight heart rate variability (HRV) and sleep quality.</p>\n        <h4>1. Evening Lighting Cues</h4>\n        <p>Overhead white LEDs suppress melatonin after evening training sessions. Switching on the <strong>LumaGym 60-Inch Warm-Sunset Corner Lamp</strong> shifts your space into a relaxing 2200K amber glow while you stretch.</p>\n        <h4>2. 15-Minute Vibrating Myofascial & Acupressure Sequence</h4>\n        <p>Spend 8 minutes rolling quads, IT bands, and thoracic spine on the <strong>VibeRoll 4-Speed Vibrating Foam Roller</strong>, followed by 10 minutes of slow nasal breathing on the <strong>SpinalReset Acupressure Mat & Neck Pillow Set</strong>.</p>\n        "}, {"slug": "weighted-vest-murph-and-compromised-running-protocol-2026", "category": "Weighted Conditioning", "title": "Weighted Training Vest 20lb Protocol: Murph Prep, Rucking & Compromised Running Intervals", "read_time": "6 min read", "summary": "How to program a 20-lb plate-carrier weighted training vest and chest-strap heart rate monitor to build Zone-2 aerobic density and leg durability without joint overload.", "recommended_skus": ["APC-E16", "APC-E21", "APC-C01", "APC-E18"], "body_html": "\n        <p>Whether you are preparing for Memorial Day Murph, building eccentric quad stamina for downhill running, or stacking Zone-2 rucking volume, a balanced <strong>Weighted Training Vest 20lb</strong> changes the biomechanical demand of every step and bodyweight rep.</p>\n        <h4>1. Why Fit &amp; Weight Distribution Matter on the Run</h4>\n        <p>Traditional sand-bag vests sag against the lower ribs and bounce violently during running intervals. The <strong>TactFit Weighted Training Vest 20lb</strong> uses an ergonomic X-frame harness with dual chest and waist tension straps that lock the load high and tight against your center of mass\u2014allowing full thoracic expansion during 1-mile bookend runs and pull-up sets.</p>\n        <h4>2. Tracking True Zone-2 Heart Rate Under Load</h4>\n        <p>Adding 20 lbs of external load elevates cardiac output by 12\u201318 BPM at any given pace. Because wrist-based optical sensors suffer from cadence lock when your arms swing or grip pull-up bars, pair your vest sessions with the <strong>PulseTrack ANT+ &amp; Bluetooth 5.0 Chest Strap Heart Rate Monitor</strong> to keep your aerobic rucking strictly below your ventilatory threshold (VT1).</p>\n        <h4>3. Post-Vest Patellar &amp; Joint Decompression</h4>\n        <p>Weighted squats, lunges, and running increase patellofemoral tendon load. Immediately after stripping off your vest and <strong>Run. Station. Repeat. Functional Race Tee</strong>, apply 15 minutes of 360-degree cold compression with the <strong>CryoSleeve Knee Ice Pack Wrap Cold Compression</strong> to calm acute synovial inflammation.</p>\n        "}, {"slug": "respiratory-muscle-training-vo2-max-and-zone-2-heart-rate-guide", "category": "VO2 Max & Aerobic Engine", "title": "Breathing Lung Trainers & Chest-Strap Monitors: How to Stop the Metaboreflex in Hybrid Races", "read_time": "5 min read", "summary": "Why diaphragm fatigue steals blood flow from your quads during high-heart-rate stations\u2014and how 5 minutes of daily inspiratory/expiratory resistance training fixes it.", "recommended_skus": ["APC-E17", "APC-E21", "APC-C06", "APC-C13"], "body_html": "\n        <p>Every hybrid racer knows the sensation of exiting the 1,000-meter SkiErg or burpee broad jump station: your lungs burn, your breathing becomes shallow, and your legs suddenly feel like concrete. That phenomenon has a physiological name\u2014the <strong>respiratory metaboreflex</strong>.</p>\n        <h4>1. How Diaphragm Fatigue Steals Leg Blood Flow</h4>\n        <p>When your inspiratory and expiratory muscles fatigue under sustained Zone-4 ventilation, your sympathetic nervous system triggers vasoconstriction in your limbs, diverting oxygenated blood away from your quads to keep your diaphragm contracting. Training with the <strong>AeroLung Breathing Lung Trainer</strong> twice daily (30 breaths morning and night) hypertrophies the diaphragm and intercostals so they resist fatigue at high minute ventilation.</p>\n        <h4>2. Pacing Threshold Repeats with ECG-Accurate Telemetry</h4>\n        <p>Pair respiratory training with precision pacing on the erg and track. The <strong>PulseTrack Chest Strap Heart Rate Monitor</strong> broadcasts simultaneous ANT+ and Bluetooth 5.0 signals to your Concept2 PM5 monitor and GPS watch so you can hold exact threshold splits without redlining early.</p>\n        "}, {"slug": "red-light-therapy-panel-vs-belt-660nm-850nm-recovery-guide", "category": "Photobiomodulation & Recovery", "title": "Red Light Therapy Panel 660nm 850nm vs. Therapy Belt Wrap: Which Recovery Setup Do You Need?", "read_time": "6 min read", "summary": "Comparing high-irradiance clinical desktop red light panels against flexible neoprene 660nm/850nm wraps, electric cupping sets, and knee cryo-compression sleeves.", "recommended_skus": ["APC-E24", "APC-E02", "APC-E19", "APC-E18"], "body_html": "\n        <p>Photobiomodulation using <strong>660nm deep red</strong> and <strong>850nm near-infrared (NIR)</strong> wavelengths has become a cornerstone of daily recovery for endurance runners and strength athletes. But should you choose a stationary <strong>Red Light Therapy Panel 660nm 850nm</strong> or a wrap-around <strong>Red Light Therapy Belt 660nm 850nm</strong>?</p>\n        <h4>1. When to Use the LumiRed Clinical Desktop Panel</h4>\n        <p>The <strong>LumiRed Red Light Therapy Panel 660nm 850nm</strong> delivers >105 mW/cm\u00b2 of focused optical irradiance across a wide treatment zone. Placed on a nightstand or desk, it provides contact-free full-torso, facial circadian, hamstring, or dual-knee illumination while you stretch or wind down before sleep.</p>\n        <h4>2. When to Wrap with the InfraFlex Belt or CryoSleeve</h4>\n        <p>For targeted joint capsules\u2014like wrapping directly around a sore patellar tendon, Achilles, or lumbar spine while working on the couch\u2014the flexible <strong>InfraFlex Red Light Therapy Belt 660nm 850nm</strong> places triple-chip LEDs flush against the skin. Alternate acute post-run cold compression using the <strong>CryoSleeve Knee Ice Pack Wrap Cold Compression</strong> with evening red-light sessions and <strong>ThermoCup Electric Cupping Therapy Set</strong> decompression for complete tendon care.</p>\n        "}, {"slug": "farmer-carry-grip-strength-liquid-chalk-and-dead-hang-guide", "category": "Grip & Station Dominance", "title": "How to Never Drop the Kettlebells: Farmer-Carry Grip Handles, Liquid Lifting Chalk & CNS Testing", "read_time": "5 min read", "summary": "Build unbreakable forearm stamina for 200m farmer carries, sled pulls, and rig work using 2-inch dead-hang handles, mess-free liquid lifting chalk, and isometric dynamometry.", "recommended_skus": ["APC-E23", "APC-E27", "APC-E09", "APC-C08"], "body_html": "\n        <p>Dropping the kettlebells three times during a 200-meter farmer carry costs 20 to 35 seconds of dead transition time and spikes your heart rate before the final wall balls. Building race-proof grip requires three elements: friction management, thick-bar flexor endurance, and CNS readiness monitoring.</p>\n        <h4>1. Friction Control in Commercial Gyms with Liquid Lifting Chalk</h4>\n        <p>Sweaty palms turn smooth kettlebell handles and sled ropes into slip hazards, yet most commercial gyms ban loose chalk blocks. A single pea-sized drop of <strong>ChalkLock Liquid Lifting Chalk</strong> dries in 10 seconds into a high-friction magnesium carbonate barrier with zero airborne dust.</p>\n        <h4>2. Thick-Grip Dead Hangs &amp; Heavy Carries</h4>\n        <p>Standard pull-up bars only measure 1.1 to 1.25 inches in diameter. Clipping the 2-inch cylindrical <strong>DeadHang Pull-Up &amp; Farmer-Carry Grip Strengthener Handles</strong> onto your pull-up bar or looping them through heavy kettlebells forces maximum recruitment of your deep forearm flexors.</p>\n        <h4>3. Objective Morning Readiness with the GripForge Dynamometer</h4>\n        <p>Before loading heavy deadlifts or carries, squeeze the <strong>GripForge 198-Lb Digital Hand Dynamometer</strong>. A drop of more than 8% below your rolling 14-day baseline signals central nervous system fatigue before you even touch a barbell.</p>\n        "}, {"slug": "away-race-travel-packing-list-collapsible-foam-roller-shoe-case", "category": "Race Travel & Packing", "title": "The Destination Race Carry-On Packing System: Collapsible Foam Roller, Carbon Shoe Vault & Duffle", "read_time": "5 min read", "summary": "How to fly carry-on only to destination hybrid races and marathons with a flat-pack collapsible travel foam roller, crush-proof carbon shoe case, and 50L tactical duffle.", "recommended_skus": ["APC-E25", "APC-E26", "APC-C14", "APC-E20"], "body_html": "\n        <p>Flying to an out-of-state race shouldn't mean checking an oversized suitcase or relying on a worn-out hotel gym foam roller the night before your wave start. With flat-pack recovery hardware, your entire race kit fits in the overhead bin.</p>\n        <h4>1. Flat-Pack Myofascial Release in Your Hotel Room</h4>\n        <p>Standard hollow foam rollers take up 35% of a carry-on bag. The <strong>MorphRoll Collapsible Travel Foam Roller</strong> folds completely flat to 2 inches thick\u2014sliding right next to your laptop\u2014and locks into a 350-lb-rated 5.5-inch deep-tissue cylinder in two seconds when you land.</p>\n        <h4>2. Protecting $250+ Carbon-Plated Race Shoes</h4>\n        <p>Stuffing PeBA super-shoes into a tightly packed bag compresses the midsole foam and bends the carbon plate before race morning. Store your race pair inside the ventilated, semi-rigid <strong>SoleVault Carbon-Plate Race Shoe &amp; Wet-Gear Case</strong> alongside your <strong>8-Station Race Day 50L Duffle</strong> and <strong>MagTripod Magnetic Gym Phone Mount</strong>.</p>\n        "}, {"slug": "lower-leg-circulation-stack-compression-boots-ems-foot-mat-cupping", "category": "Lower-Body Recovery", "title": "The Ultimate Lower-Leg Flushing Stack: Air Compression Recovery Boots, EMS Foot Mat & Smart Cupping", "read_time": "6 min read", "summary": "Eliminate heavy legs, plantar fascia tightness, and calf knots between double-threshold days using pneumatic compression boots, bio-electric EMS foot mats, and dynamic cupping.", "recommended_skus": ["APC-E12", "APC-E22", "APC-E19", "APC-E01"], "body_html": "\n        <p>High-mileage runners and hybrid athletes accumulate massive eccentric load in the soleus, gastrocnemius, plantar fascia, and quads. Waiting passively for soreness to fade limits how much quality threshold work you can absorb each week.</p>\n        <h4>1. Passive Desk Flushing with the NeuroStep EMS Foot Mat</h4>\n        <p>Sitting at a desk for 8 hours after a morning run causes venous pooling in the lower extremities. Placing your bare feet on the <strong>NeuroStep EMS Foot Massager Circulation Mat</strong> for 15 minutes fires gentle bio-electric pulses through the intrinsic foot muscles and calf venous pump\u2014relieving plantar fascia stiffness while you answer emails.</p>\n        <h4>2. Targeted Myofascial Decompression with Smart Electric Cupping</h4>\n        <p>Where foam rollers compress tight tissue downward, the <strong>ThermoCup Smart Electric Cupping Therapy Set</strong> uses rhythmic negative-pressure suction and 650nm red light to lift adhered fascia away from sore calves, hamstrings, and IT bands.</p>\n        <h4>3. Evening Lymphatic Drainage in Sequential Compression Boots</h4>\n        <p>Finish the evening with 20 minutes inside the <strong>AirRecover Full-Leg Sequential Leg Air Compression Recovery Boots</strong> after a quick flush with the <strong>ApexPulse Pro 3200 RPM Percussion Massager</strong> so your legs wake up fresh for tomorrow's session.</p>\n        "}];

let currentDept = 'all';
let currentPriceFilter = 'all';
let topRatedOnly = false;
let cart = [];
let selectedModalSize = 'L';
let selectedModalColor = 'Vintage Black';
let selectedPaymentMethod = 'card';

function formatPriceHtml(price, listPrice) {
  const whole = Math.floor(price);
  const cents = Math.round((price - whole) * 100).toString().padStart(2, '0');
  const listHtml = listPrice ? `<span class="PriceList">List: $${listPrice.toFixed(2)}</span>` : '';
  return `<span class="PriceWhole"><sup>$</sup>${whole}<sup>${cents}</sup></span>${listHtml}`;
}

function setFilter(dept) {
  currentDept = dept;
  const select = document.getElementById('deptSelect');
  if (select && [...select.options].some(o => o.value === dept)) {
    select.value = dept;
  }
  document.querySelectorAll('[data-dept]').forEach(el => {
    el.classList.toggle('active', el.dataset.dept === dept);
  });
  document.getElementById('activeDeptLabel').textContent = dept === 'all' ? 'All Departments' : dept;
  renderProducts();
}

function setPriceFilter(priceKey) {
  currentPriceFilter = priceKey;
  document.querySelectorAll('[data-price]').forEach(el => {
    el.classList.toggle('active', el.dataset.price === priceKey);
  });
  renderProducts();
}

function toggleTopRatedOnly() {
  topRatedOnly = !topRatedOnly;
  const btn = document.querySelector('.RatingFilterBtn');
  if (btn) btn.classList.toggle('active', topRatedOnly);
  renderProducts();
}

function resetAllFilters() {
  currentDept = 'all';
  currentPriceFilter = 'all';
  topRatedOnly = false;
  document.getElementById('searchInput').value = '';
  document.getElementById('sortSelect').value = 'featured';
  setFilter('all');
  setPriceFilter('all');
}

function renderProducts() {
  const q = (document.getElementById('searchInput').value || '').trim().toLowerCase();
  const sortBy = document.getElementById('sortSelect').value;
  const grid = document.getElementById('productGrid');

  let filtered = PRODUCTS.filter(p => {
    if (currentDept !== 'all' && p.dept !== currentDept) return false;
    if (currentPriceFilter === 'under40' && p.retail_price >= 40) return false;
    if (currentPriceFilter === '40to80' && (p.retail_price < 40 || p.retail_price > 80)) return false;
    if (currentPriceFilter === 'over80' && p.retail_price < 80) return false;
    if (topRatedOnly && p.rating < 4.8) return false;
    if (q) {
      const hay = `${p.title} ${p.seo_title || ""} ${p.short_desc} ${p.category} ${p.dept}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }
    return true;
  });

  if (sortBy === 'price-asc') filtered.sort((a, b) => a.retail_price - b.retail_price);
  else if (sortBy === 'price-desc') filtered.sort((a, b) => b.retail_price - a.retail_price);
  else if (sortBy === 'reviews') filtered.sort((a, b) => b.reviews - a.reviews);
  else if (sortBy === 'rating') filtered.sort((a, b) => b.rating - a.rating || b.reviews - a.reviews);

  document.getElementById('resultsCount').textContent = filtered.length;

  grid.innerHTML = filtered.map(p => {
    let badgeClass = '';
    if (p.badge === 'Top Rated') badgeClass = 'top-rated';
    else if (p.badge === 'New Release') badgeClass = 'new-release';
    const badgeHtml = p.badge ? `<span class="ProductCard__Badge ${badgeClass}">${p.badge}</span>` : '';

    return `
      <article class="ProductCard" id="${p.handle}">
        <div class="ProductCard__Media" onclick="openProductModal('${p.id}')">
          ${badgeHtml}
          <img src="${p.image}" alt="${p.title}" loading="lazy" />
        </div>
        <div class="ProductCard__Body">
          <div class="ProductCard__Category">${p.category}</div>
          <h3 class="ProductCard__Title"><a href="products/${p.handle}.html" onclick="if(!event.ctrlKey&&!event.metaKey){event.preventDefault();openProductModal('${p.id}');}">${p.title}</a></h3>
          <div class="ProductCard__RatingRow">
            <span class="Stars">★★★★★</span>
            <span class="ProductCard__RatingNum">${p.rating.toFixed(1)}</span>
            <span class="ProductCard__ReviewCount">(${p.reviews})</span>
          </div>
          <div class="ProductCard__PriceRow">
            ${formatPriceHtml(p.retail_price, p.list_price)}
          </div>
          <div class="ProductCard__Delivery"><strong>${p.ship_time}</strong></div>
          <div class="ProductCard__Stock">${p.stock_status}</div>
          <p class="ProductCard__Desc">${p.short_desc}</p>
          <div class="ProductCard__Actions">
            <button class="Btn Btn--Cart" onclick="addToCart('${p.id}')">Add to Cart</button>
            <button class="Btn Btn--QuickView" onclick="openProductModal('${p.id}')">Details</button>
          </div>
        </div>
      </article>
    `;
  }).join('');
}

function openProductModal(sku) {
  const p = PRODUCTS.find(x => x.id === sku);
  if (!p) return;
  selectedModalSize = 'L';
  selectedModalColor = 'Vintage Black';
  renderProductModalContent(p);
  document.getElementById('productModal').classList.add('open');
}

function renderProductModalContent(p) {
  const activeImg = (selectedModalColor === 'Bone White' && p.alt_image) ? p.alt_image : p.image;
  const colorHtml = p.alt_image ? `
    <div>
      <strong style="font-size:12px;display:block;margin-bottom:4px;">Color: ${selectedModalColor}</strong>
      <div class="SwatchRow">
        <button class="OptionBtn ${selectedModalColor === 'Vintage Black' ? 'active' : ''}" onclick="selectedModalColor='Vintage Black';renderProductModalContent(PRODUCTS.find(x=>x.id==='${p.id}'))">Vintage Black</button>
        <button class="OptionBtn ${selectedModalColor === 'Bone White' ? 'active' : ''}" onclick="selectedModalColor='Bone White';renderProductModalContent(PRODUCTS.find(x=>x.id==='${p.id}'))">Bone White</button>
      </div>
    </div>
  ` : '';

  const sizeHtml = p.has_sizes ? `
    <div>
      <strong style="font-size:12px;display:block;margin-bottom:4px;">Size: ${selectedModalSize}</strong>
      <div class="SizeRow">
        ${['S', 'M', 'L', 'XL', '2XL'].map(sz => `
          <button class="OptionBtn ${selectedModalSize === sz ? 'active' : ''}" onclick="selectedModalSize='${sz}';renderProductModalContent(PRODUCTS.find(x=>x.id==='${p.id}'))">${sz}</button>
        `).join('')}
      </div>
    </div>
  ` : '';

  document.getElementById('productModalBody').innerHTML = `
    <div class="ProdModalGrid">
      <div class="ProdModalMedia">
        <img src="${activeImg}" alt="${p.title}" />
      </div>
      <div>
        <div class="ProductCard__Category">${p.dept} · ${p.category} · <a href="products/${p.handle}.html" style="color:#007185;text-decoration:underline;">Full Product Page &rarr;</a></div>
        <h2 style="font-size:21px;font-weight:700;margin:4px 0 8px;">${p.title}</h2>
        <div class="ProductCard__RatingRow" style="margin-bottom:12px;">
          <span class="Stars">★★★★★</span>
          <span class="ProductCard__RatingNum">${p.rating.toFixed(1)} out of 5</span>
          <span class="ProductCard__ReviewCount">(${p.reviews} verified ratings)</span>
        </div>
        <div class="ProductCard__PriceRow" style="margin-bottom:8px;">
          ${formatPriceHtml(p.retail_price, p.list_price)}
        </div>
        <div class="ProductCard__Delivery"><strong>${p.ship_time}</strong></div>
        <div class="ProductCard__Stock" style="margin-bottom:14px;">${p.stock_status}</div>
        ${colorHtml}
        ${sizeHtml}
        <ul class="HighlightsList">
          ${(p.highlights || []).map(h => `<li>${h}</li>`).join('')}
        </ul>
        <div class="ReviewSnippetBox">
          <strong>Verified Athlete Review:</strong> "${p.review_quote}"
        </div>
        <div style="display:flex;gap:10px;">
          <button class="Btn Btn--Cart" style="padding:11px 18px;" onclick="addToCart('${p.id}', '${p.has_sizes ? selectedModalSize : ''}', '${p.alt_image ? selectedModalColor : ''}');closeProductModal();">Add to Cart</button>
          <button class="Btn Btn--BuyNow" style="padding:11px 18px;flex:1;" onclick="addToCart('${p.id}', '${p.has_sizes ? selectedModalSize : ''}', '${p.alt_image ? selectedModalColor : ''}', false);closeProductModal();openCheckoutModal();">Buy Now with Card</button>
        </div>
      </div>
    </div>
  `;
}

function closeProductModal() {
  document.getElementById('productModal').classList.remove('open');
}

function renderGuides() {
  const grid = document.getElementById('guidesGrid');
  grid.innerHTML = GUIDES.map((g, idx) => `
    <article class="GuideCard">
      <div>
        <div class="GuideCard__Cat">${g.category}</div>
        <h3>${g.title}</h3>
        <p>${g.summary}</p>
      </div>
      <div class="GuideCard__Footer">
        <span>${g.read_time}</span>
        <button class="Btn Btn--QuickView" onclick="openArticle(${idx})">Read Guide</button>
      </div>
    </article>
  `).join('');
}

function openArticle(idx) {
  const g = GUIDES[idx];
  document.getElementById('modalKeyword').textContent = g.category + ' · ' + g.read_time;
  document.getElementById('modalTitle').textContent = g.title;
  document.getElementById('modalBody').innerHTML = g.body_html;
  const recProds = PRODUCTS.filter(p => g.recommended_skus.includes(p.id));
  document.getElementById('modalProducts').innerHTML = recProds.map(p => `
    <div style="background:#f8f9fa;border:1px solid #e3e6e8;border-radius:8px;padding:10px;font-size:12px;display:flex;flex-direction:column;justify-content:space-between;">
      <div>
        <img src="${p.image}" alt="${p.title}" style="width:100%;height:95px;object-fit:contain;background:#fff;border-radius:6px;padding:6px;margin-bottom:6px;" />
        <strong style="display:block;margin-bottom:4px;line-height:1.3;">${p.title}</strong>
      </div>
      <div>
        <span style="color:#0f1111;font-weight:700;font-size:14px;">$${p.retail_price.toFixed(2)}</span>
        <button class="Btn Btn--Cart Btn--Full" style="margin-top:6px;padding:6px 10px;" onclick="addToCart('${p.id}');closeArticle();">Add to Cart</button>
      </div>
    </div>
  `).join('');
  document.getElementById('articleModal').classList.add('open');
}

function closeArticle() {
  document.getElementById('articleModal').classList.remove('open');
}

function addToCart(sku, size = '', color = '', openDrawer = true) {
  const prod = PRODUCTS.find(p => p.id === sku);
  if (!prod) return;
  const variantLabel = [color, size ? `Size ${size}` : (prod.has_sizes ? 'Size L' : '')].filter(Boolean).join(' · ');
  const key = `${sku}__${variantLabel}`;
  const existing = cart.find(i => i.key === key);
  if (existing) existing.qty += 1;
  else cart.push({ ...prod, key, variantLabel, qty: 1 });
  updateCartUI();
  if (openDrawer) document.getElementById('cartDrawer').classList.add('open');
}

function changeQty(key, delta) {
  const item = cart.find(i => i.key === key);
  if (!item) return;
  item.qty += delta;
  if (item.qty <= 0) cart = cart.filter(i => i.key !== key);
  updateCartUI();
}

function updateCartUI() {
  const count = cart.reduce((s, i) => s + i.qty, 0);
  const subtotal = cart.reduce((s, i) => s + i.retail_price * i.qty, 0);
  document.getElementById('cartCount').textContent = count;
  document.getElementById('cartItemCountLabel').textContent = count;
  document.getElementById('cartSubtotal').textContent = '$' + subtotal.toFixed(2);

  const container = document.getElementById('cartItems');
  if (!cart.length) {
    container.innerHTML = '<p style="color:#565959;font-size:14px;padding:20px 0;">Your shopping cart is empty.</p>';
    return;
  }
  container.innerHTML = cart.map(item => `
    <div style="display:flex;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid #e3e6e8;font-size:13px;">
      <img src="${item.image}" alt="${item.title}" style="width:62px;height:62px;object-fit:contain;border:1px solid #e3e6e8;border-radius:6px;padding:4px;background:#fff;" />
      <div style="flex:1;">
        <strong style="display:block;line-height:1.3;">${item.title}</strong>
        ${item.variantLabel ? `<span style="font-size:11.5px;color:#565959;display:block;">${item.variantLabel}</span>` : ''}
        <span style="color:#007600;font-size:11.5px;font-weight:600;">In Stock · Free US Shipping</span>
        <div style="display:flex;align-items:center;gap:8px;margin-top:6px;">
          <button class="IconBtn" style="width:24px;height:24px;font-size:13px;" onclick="changeQty('${item.key}', -1)">−</button>
          <strong>${item.qty}</strong>
          <button class="IconBtn" style="width:24px;height:24px;font-size:13px;" onclick="changeQty('${item.key}', 1)">+</button>
          <span style="margin-left:auto;font-weight:700;">$${(item.retail_price * item.qty).toFixed(2)}</span>
        </div>
      </div>
    </div>
  `).join('');
}

function toggleCart() {
  document.getElementById('cartDrawer').classList.toggle('open');
}

function openCheckoutModal() {
  if (!cart.length) return;
  document.getElementById('cartDrawer').classList.remove('open');
  renderCheckoutForm();
  document.getElementById('checkoutModal').classList.add('open');
}

function closeCheckoutModal() {
  document.getElementById('checkoutModal').classList.remove('open');
}

function selectPayMethod(m) {
  selectedPaymentMethod = m;
  document.querySelectorAll('.PayOption').forEach(el => {
    el.classList.toggle('selected', el.dataset.pay === m);
  });
}

function renderCheckoutForm() {
  const subtotal = cart.reduce((s, i) => s + i.retail_price * i.qty, 0);

  document.getElementById('checkoutModalBody').innerHTML = `
    <div class="CheckoutHeader">
      <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#007600" stroke-width="2.2"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
      <div>
        <h2 style="font-size:19px;font-weight:800;">Secure Express Checkout</h2>
        <span style="font-size:12px;color:#565959;">256-Bit SSL Encrypted · PCI-DSS Level 1 Hosted Payment Protection</span>
      </div>
    </div>

    <div class="SecurityBanner">
      <strong>Card Security Guarantee:</strong> To protect your card data under PCI-DSS Level 1 standards, raw card numbers and CVV codes are never entered on static forms—payment completes via encrypted Stripe Card &amp; Apple Pay checkout at <strong>apexhybridco.com</strong>.
    </div>

    <form onsubmit="submitSecureOrder(event)">
      <h4 style="font-size:13.5px;margin-bottom:8px;">1. Shipping Address (United States)</h4>
      <div class="FormGrid">
        <div class="FormField">
          <label>Full Name *</label>
          <input type="text" id="chkName" required placeholder="Alex Morgan" />
        </div>
        <div class="FormField">
          <label>Email for Tracking &amp; Receipt *</label>
          <input type="email" id="chkEmail" required placeholder="alex@example.com" />
        </div>
        <div class="FormField full">
          <label>Street Address *</label>
          <input type="text" id="chkStreet" required placeholder="17911 Von Karman Ave, Suite 300" />
        </div>
        <div class="FormField">
          <label>City &amp; State *</label>
          <input type="text" id="chkCity" required placeholder="Irvine, CA" />
        </div>
        <div class="FormField">
          <label>ZIP Code *</label>
          <input type="text" id="chkZip" required placeholder="92614" />
        </div>
      </div>

      <h4 style="font-size:13.5px;margin-bottom:8px;">2. Select Encrypted Payment Method</h4>
      <div class="PayOption selected" data-pay="card" onclick="selectPayMethod('card')">
        <div>
          <strong style="font-size:13px;display:block;">Credit or Debit Card (Encrypted Stripe Card &amp; Apple Pay Checkout)</strong>
          <span style="font-size:11.5px;color:#565959;">Visa, Mastercard, American Express, Discover — 256-bit SSL encrypted</span>
        </div>
        <span style="font-size:12px;font-weight:700;color:#007185;">Card / Apple Pay</span>
      </div>

      <div style="background:#f8f9fa;border:1px solid #e3e6e8;border-radius:8px;padding:12px 14px;margin:14px 0;font-size:13px;">
        <div style="display:flex;justify-content:space-between;margin-bottom:4px;">
          <span>Items (${cart.reduce((s,i)=>s+i.qty,0)}):</span>
          <span>$${subtotal.toFixed(2)}</span>
        </div>
        <div style="display:flex;justify-content:space-between;margin-bottom:6px;color:#007600;font-weight:600;">
          <span>US Ground Shipping (2–4 Business Days):</span>
          <span>FREE</span>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:16px;font-weight:800;padding-top:6px;border-top:1px solid #e3e6e8;">
          <span>Order Total:</span>
          <span>$${subtotal.toFixed(2)}</span>
        </div>
      </div>

      <button type="submit" class="Btn Btn--Checkout Btn--Full">
        Complete Secure Order ($${subtotal.toFixed(2)})
      </button>
    </form>
  `;
}

function submitSecureOrder(e) {
  e.preventDefault();
  const name = document.getElementById('chkName').value.trim();
  const email = document.getElementById('chkEmail').value.trim();
  const street = document.getElementById('chkStreet').value.trim();
  const city = document.getElementById('chkCity').value.trim();
  const zip = document.getElementById('chkZip').value.trim();
  const subtotal = cart.reduce((s, i) => s + i.retail_price * i.qty, 0);
  const orderId = 'APX-' + Math.floor(100000 + Math.random() * 900000);

  const lines = cart.map(i => `- ${i.qty}x ${i.title} ${i.variantLabel ? '('+i.variantLabel+')' : ''} — $${(i.retail_price * i.qty).toFixed(2)}`).join('\n');
  const mailSubject = encodeURIComponent(`Order ${orderId} — Secure Card Checkout Link Request ($${subtotal.toFixed(2)})`);
  const mailBody = encodeURIComponent(
    `Order ID: ${orderId}\nCustomer: ${name} (${email})\nShip To: ${street}, ${city} ${zip}\nPayment Method: Encrypted Card / Apple Pay Link\n\nItems:\n${lines}\n\nTotal: $${subtotal.toFixed(2)} (Free US Shipping)`
  );

  document.getElementById('checkoutModalBody').innerHTML = `
    <div style="text-align:center;padding:12px 6px;">
      <div style="width:48px;height:48px;border-radius:999px;background:#dcfce7;color:#166534;display:inline-flex;align-items:center;justify-content:center;font-size:24px;font-weight:800;margin-bottom:10px;">✓</div>
      <h2 style="font-size:21px;font-weight:800;margin-bottom:6px;">Order Reserved · #${orderId}</h2>
      <p style="font-size:13.5px;color:#565959;margin-bottom:16px;">
        Thank you, <strong>${name}</strong>. Your items are allocated for dispatch to <strong>${city} ${zip}</strong>.
      </p>
      <div style="background:#f8f9fa;border:1px solid #e3e6e8;border-radius:8px;padding:14px;text-align:left;font-size:13px;margin-bottom:16px;">
        <strong style="display:block;margin-bottom:6px;">Order Summary (#${orderId}):</strong>
        ${cart.map(i => `<div style="display:flex;justify-content:space-between;margin-bottom:4px;"><span>${i.qty}× ${i.title}</span><strong>$${(i.retail_price*i.qty).toFixed(2)}</strong></div>`).join('')}
        <div style="display:flex;justify-content:space-between;border-top:1px solid #e3e6e8;padding-top:6px;margin-top:6px;font-weight:800;">
          <span>Total Due (Free US Shipping):</span>
          <span>$${subtotal.toFixed(2)}</span>
        </div>
      </div>
      <div style="display:flex;flex-direction:column;gap:8px;">
        <a href="mailto:nolcorpllc@gmail.com?subject=${mailSubject}&body=${mailBody}" class="Btn Btn--Checkout Btn--Full">
          Send Order #${orderId} &amp; Receive Encrypted Stripe/Card Payment Link
        </a>
        <button class="Btn Btn--QuickView Btn--Full" style="border-radius:8px;" onclick="cart=[];updateCartUI();closeCheckoutModal();">Done</button>
      </div>
    </div>
  `;
}

document.addEventListener('DOMContentLoaded', () => {
  renderProducts();
  renderGuides();
  updateCartUI();
  const params = new URLSearchParams(window.location.search);
  const buySku = params.get('buy');
  const addSku = params.get('add');
  if (buySku && PRODUCTS.some(p => p.id === buySku)) {
    addToCart(buySku, '', '', false);
    openCheckoutModal();
  } else if (addSku && PRODUCTS.some(p => p.id === addSku)) {
    addToCart(addSku, '', '', true);
  }
});
